import pandas as pd

def find_products(products: pd.DataFrame) -> pd.DataFrame:
    pattern = r'(?:^|\s)SN\d{4}-\d{4}(?:$|[^\d])'
    valid_mask = products['description'].str.contains(pattern, regex=True, na=False)
    return products[valid_mask].sort_values(by='product_id', ascending=True)
